    coinmic: { pole: 15, tap: { left: -7, top: -32, right: 7, bottom: 1 }, mouth: { dx: 0, dy: -26 }, sound: 'mic-on' },
    bullhorn: { pole: 15, tap: { left: -7, top: -34, right: 7, bottom: 1 }, mouth: { dx: 0, dy: -28 }, sound: 'mic-on' },
    psgmic: { pole: 15, tap: { left: -7, top: -32, right: 7, bottom: 1 }, mouth: { dx: 0, dy: -26 }, sound: 'mic-on' },
