    heartbox: { x: 260, y: 36, w: 29, h: 54 }, candledinner: { x: 252, y: 58, w: 50, h: 37 },
    plumtree: { x: 258, y: 45, w: 42, h: 50 }, lionhead: { x: 264, y: 48, w: 28, h: 47 },
