  const wallWidthOf = (kind) => WALL_WIDTHS[kind] || 32;

  /* ---------------------------------------------- the floor upstairs */

  /*
   * Claude runs with no Terminal to sit in, started by a script or another
   * app, have desks of their own on a second floor: the server room, up the
   * elevator at the left end of the back wall. Nothing there takes keys,
   * holds or hires; the people at its desks just work, as they do downstairs.
   */
  /**
   * The elevator, on the back wall of both floors, by the entrance: its frame's left edge, width and top, just left of
   * the door's frame (205) and clear of its clock. Over its lamp, the alarm's warning light downstairs and the 2F
   * plate upstairs; its badge on its doors, reaching left as far as `side` where it's long, on a phone, so the wall's
   * pieces stop short of that. Moved along the wall, it's all moved together: see `shiftsOf`.
   */
  const ELEVATOR = {
    get x() { return ELEVATOR_AT.x + shiftsOf().lift; }, w: 20, top: 14, get side() { return ELEVATOR_AT.side + shiftsOf().lift; },
  };
  /** Where the elevator's frame and its badge's reach start as the room comes, for `ELEVATOR` to move from. */
  const ELEVATOR_AT = { x: 182, side: 171 };
  /** How long the ride between the floors takes, in seconds: the room slides by in that time. */
  const RIDE_LENGTH = 0.4;
  /** How long the doors stay open after the ding, in seconds, from when the ride ends. */
  const DOORS_OPEN_FOR = 1.3;
  /** The most desks on a floor upstairs; anyone past the top floor's is counted in the elevator's floor list. */
  const UPSTAIRS_MOST = 12;
  /** The most floors, the ground floor's among them: the apps send each of them in `floors`. */
  const FLOORS_MOST = 6;
  /** The elevator's floor list, in art pixels: its width, each floor's row (taller upright, for a finger), and the margin round them. */
  const PICKER = { w: 96, get row() { return shape === TALL ? 18 : 12; }, pad: 3 };
  /** The call button's plate, on the wall just left of the elevator's frame: its left edge from the frame's, and its top. */
  const CALL_PLATE = { dx: -6, top: 30, w: 4, h: 9 };
  /**
   * The desks upstairs, oldest first in reading order. On its side, four to
   * a row, the fourth row's desks past the corridor where the lounge would
   * be; upright, three to a row, a fourth row under the others, where the
   * lounge's wall would be: there's none upstairs.
   */
  const UPSTAIRS_DESKS = {
    wide: DESK_ROWS.flatMap((y) => [...DESK_COLUMNS, 232].map((x) => ({ x, y, off: false }))),
    tall: [...DESK_ROWS, 190].flatMap((y) => DESK_COLUMNS.map((x) => ({ x, y, off: false }))),
  };
  /** The corner of racks: the first rack's left edge, the floor they stand on, how many, and the cable tray's height above the floor. */
  const RACKS = { wide: { x: 284, base: 60, count: 3, tray: 46 }, tall: { x: 8, base: 290, count: 5, tray: 48 } };
  /** Where this device keeps the floor its viewer was last on. */
  const FLOOR_KEY = 'office-floor';
  /** The server room's colours: its cool paint and raised floor, its racks, and the elevator's brushed steel and lamp. */
  const SERVER_ROOM = {
    wall: 0x3e4f5c, top: 0x2b3843, wallSeam: 0x35444f, vent: 0x2a3640, wainscot: 0x2e3b46, rail: 0x6b7f8d,
    tile: 0x7f8c96, tileLight: 0x8d9aa4, tileSeam: 0x66727b, holes: 0x5a656e,
    rack: 0x1c2026, rackFace: 0x272c34, unit: 0x353b45, unitTop: 0x434a56, plinth: 0x14171c,
    tray: 0x9aa3ad, trayShade: 0x5d6670, cables: [0x3f7fd0, 0xe0b040, 0x8a93a0],
    leds: [0x3fdc6f, 0x3fdc6f, 0xffb648, 0x4c9cff],
    steel: 0x8d97a1, steelLight: 0xbcc5cd, steelDark: 0x57616b, leaf: 0xa4aeb8, leafLight: 0xc6cfd7, seam: 0x3c444d,
    car: 0x2b3038, carLight: 0xffe6a8, lampOn: 0xffb648, lampOff: 0x4a3c30,
  };
  /** The headless desks' badge, a little robot, on the front of each desk upstairs: its antenna's light blinks. */
  const ROBOT_BADGE = ['...a...', '.GGGGG.', 'GgggggG', 'GgcgcgG', 'GgkkkgG', '.GGGGG.'];
  const ROBOT_INKS = { G: 0x7d838f, g: 0xc4c8d0, c: 0x6fe0ff, k: 0x1f2129 };
  /** What the floor upstairs puts away, in either shape: the whole lounge, with its button and mic. */
  const UPSTAIRS_AWAY = ['wall', 'corner', 'couch', 'pong', 'plant', 'button', 'mic'];

  /**
   * The floor upstairs, furnished from the room downstairs: your team's
   * looks and the sky stay as they are, the rest is the server room's own.
   * Its floor and paint are drawn by drawOffice's drawUpstairs parts; those
   * named here are only what other parts read.
   */
  function upstairsRoomOf(room) {
    const away = Object.fromEntries(UPSTAIRS_AWAY.map((part) => [part, { ...STANDARD_PIECE, off: true }]));
    // The door and the elevator where they are downstairs: the same shaft, the same stairwell
    const plan = (side) => ({ ...away, ...Object.fromEntries(['door', 'elevator'].map((part) => [part, (room.plan && room.plan[side][part]) || STANDARD_PIECE])) });
    return {
      ...room, upstairs: true, server: true, preset: 'yours',
      floor: 'tiles', lounge: 'tiles', paint: 'slate', loungePaint: 'auto', wall: ['bare', 'bare', 'bare', 'bare', 'bare'],
      corner: 'none', pet: 'none', pets: [], staff: 'none', door: 'standard', drift: 'none', season: 'off', fireworks: 'off',
      workspace: 'desk', monitor: 'standard', desk: 'black', chair: 'grey',
      plan: { wide: plan('wide'), tall: plan('tall'), added: { wide: [], tall: [] }, hung: { wide: null, tall: null } },
    };
  }

  /**
   * A floor upstairs in the style setup gave it: "server" is the server room
   * (see upstairsRoomOf), "" the style downstairs as it is, any other that
   * style as roomOf furnishes it. Each is laid out as upstairs is: its lounge
   * put away, the same elevator and door, your team as downstairs, and no
   * pets, staff or fireworks.
   */
  function floorRoomOf(room, preset) {
    if (preset === 'server') return upstairsRoomOf(room);
    const styled = preset && ROOM_STYLES[preset] ? { ...roomOf({ ...room, preset, plan: null }), team: room.team, dress: room.dress } : room;
    return {
      ...styled, upstairs: true, server: false, pet: 'none', pets: [], staff: 'none', fireworks: 'off',
      plan: upstairsRoomOf(room).plan,
    };
  }

  /**
   * The floors in a snapshot, the ground floor first, each with its name, its
   * style and the desks on it, as the apps send them in `floors`. A snapshot
   * from an app before them has one floor upstairs, the server room, with its
   * `upstairs` desks.
   */
  function floorsOf(snapshot) {
    const given = snapshot && Array.isArray(snapshot.floors) ? snapshot.floors.slice(0, FLOORS_MOST) : [];
    if (given.length >= 2) {
      return given.map((floor, i) => {
        const f = floor && typeof floor === 'object' ? floor : {};
        const name = typeof f.name === 'string' ? f.name.replace(/[\x00-\x1f\x7f]/g, '').trim().slice(0, 24) : '';
        return { n: i + 1, name: name || `${i + 1}F`, preset: typeof f.preset === 'string' ? f.preset : '', desks: Array.isArray(f.desks) ? f.desks : [] };
      });
    }
    const up = snapshot && snapshot.upstairs && Array.isArray(snapshot.upstairs.desks) ? snapshot.upstairs.desks : [];
    return [{ n: 1, name: '1F', preset: '', desks: [] }, { n: 2, name: '2F', preset: 'server', desks: up }];
  }

  /** How many wait past the top floor, as the snapshot says: its `floorsOverflow`, or before floors, upstairs' overflow. */
  function pastTheTop(snapshot) {
    const count = snapshot && Array.isArray(snapshot.floors) ? snapshot.floorsOverflow : snapshot && snapshot.upstairs && snapshot.upstairs.overflow;
    return Number(count) > 0 ? Math.round(Number(count)) : 0;
  }

  /**
   * Runs `fn` with the room swapped for `world`'s, the floor upstairs: its
   * furnishing, desks, spots and walking grid, so an Office and drawOffice
   * work there just as they do downstairs. Laid out again for the room's
   * shape whenever that has changed, saying so with `world.moved`.
   * Everything is as it was afterwards.
   */
  function onFloor(world, fn) {
    const kept = { decor, DESKS, spots, boardSpots, stormSpots, floor };
    decor = world.decor;
    if (world.shape !== shape) {
      Object.assign(world, {
        shape, moved: true, floor: null,
        DESKS: desksOf(decor), spots: spotsOf(decor), boardSpots: boardSpotsOf(decor), stormSpots: stormSpotsOf(decor),
      });
    }
    ({ DESKS, spots, boardSpots, stormSpots, floor } = world);
    try {
      return fn();
    } finally {
      // The walking grid, once built, is kept for next time.
      Object.assign(world, { DESKS, floor });
      ({ decor, DESKS, spots, boardSpots, stormSpots, floor } = kept);
    }
  }

  /**
   * A floor's desks from the snapshot (see floorsOf), as seats upstairs: each
   * with an id of its own (the portable viewer's have only a name and a
   * state), named after its folder, and with nothing to press.
   */
  function upstairsSeatsOf(given, ahead) {
    const named = new Map();
    const keys = given.filter((entry) => entry && typeof entry === 'object').slice(0, UPSTAIRS_MOST).map((entry) => {
      const name = String(entry.project || entry.name || '');
      const n = (named.get(name) || 0) + 1;
      named.set(name, n);
      const id = typeof entry.id === 'string' && entry.id ? entry.id : `upstairs:${name}:${n}`;
      return { session: { ...entry, id, name, project: name, state: STANDARD_STATES[entry.state] ? entry.state : 'idle' } };
    });
    return seatsOf({ keys }, ahead).map((seat) => ({
      pin: null,
      session: { ...seat.session, maxPressedAt: null, messagedAt: null, role: null, keys: false, fire: false, mic: false, dial: false },
    }));
  }

  /**
   * The wall's line, that pieces hang along: from WALL_START, clear of the menu's corner, to the room's far end. On its
   * side, it's the back wall, the lounge's part past the door; upright, the back wall to the room's width, and then the
   * lounge's own wall, from LOUNGE_LINE on, as long again. The apps' Layout.swift and layout.go keep WALL_LENGTH.
   */
  const WALL_START = 24;
  const LOUNGE_LINE = TALL.width;
  const WALL_LENGTH = LOUNGE_LINE * 2;
  /** Where along the line the wall's line runs in each shape, end to end, for the editor. */
  const WALL_RANGE = { wide: [WALL_START, WIDTH - 2], tall: [WALL_START, WALL_LENGTH - 2] };
  /** The pinboard on the lounge's own wall, held upright, between the cooler and the doorway: its middle, in the wide room. */
  const LOUNGE_PINBOARD = 364;
  /** Where that pinboard is: as it comes, or just past the doorway, where the door's been moved over it. */
  function loungePinboard(room = decor) {
    const door = shiftsOf(room).door, x = LOUNGE_PINBOARD + TALL.offsets.wall.x, half = wallWidthOf('pinboard') / 2;
    const over = DOOR_FRAME.left + door - 2 < x + half && DOOR_FRAME.right + door + 2 > x - half;
    return over ? Math.ceil(DOOR_FRAME.right + door + 3 + half) - TALL.offsets.wall.x : LOUNGE_PINBOARD;
  }
  /** The furthest left the elevator goes, its badge's reach at the wall's start: the door goes no further left than it. */
  const LIFT_LEFTMOST = WALL_START - ELEVATOR_AT.side;

  /**
   * How far the elevator and the door are moved along the back wall from
   * where they come, in the room's shape now, as arranged: only ever left,
   * as the door is at the lounge, the door always right of the elevator.
   * Upstairs, they're where they are downstairs.
   */
  function shiftsOf(room = decor) {
    const lift = Math.max(LIFT_LEFTMOST, Math.min(0, pieceOf('elevator', room).x));
    return { lift, door: Math.max(lift, Math.min(0, pieceOf('door', room).x)) };
  }

  /**
   * The stretches of the wall's line pieces can hang on, edge to edge, in
   * the room's shape now: clear of the elevator, the doorway and the
   * lounge's window wherever they're moved, and upright, of the lounge's
   * doorway, under the back door, and its pinboard.
   */
  function wallStretches(room = decor) {
    const { lift, door } = shiftsOf(room), tall = shape === TALL;
    const walls = tall ? [[WALL_START, LOUNGE_LINE - 2], [LOUNGE_LINE + 2, WALL_LENGTH - 2]] : [[WALL_START, WIDTH - 2]];
    const away = [
      [ELEVATOR_AT.side + lift - 2, ELEVATOR_AT.x + ELEVATOR.w + lift + 2],
      [DOOR_FRAME.left + door - 2, DOOR_FRAME.right + door + 2],
    ];
    if (tall && !room.upstairs) {
      away.push([LOUNGE_LINE + DOOR_FRAME.left + door - 2, LOUNGE_LINE + DOOR_FRAME.right + door + 2]);
      const pinboard = LOUNGE_LINE + loungePinboard(room) + TALL.offsets.wall.x, half = wallWidthOf('pinboard') / 2;
      away.push([pinboard - half - 2, pinboard + half + 2]);
    }
    const pane = pieceOf('window', room);
    if (!pane.off && !room.upstairs) {
      const left = PIECE_BOXES.window.x + pane.x + (tall ? LOUNGE_LINE + TALL.offsets.window.x : 0);
      away.push([left - 1, left + PIECE_BOXES.window.w + 1]);
    }
    return walls.flatMap((wall) => away.reduce((parts, [l, r]) => parts.flatMap(([a, b]) => (r <= a || l >= b ? [[a, b]]
      : [[a, Math.min(b, l)], [Math.max(a, r), b]].filter(([from, to]) => to > from))), [wall]));
  }

  /** Where `x`, along the wall's line, is in the room: on the back wall, or upright, past LOUNGE_LINE, on the lounge's wall, `dy` below it. */
  const onWallAt = (x) => (shape === TALL && x >= LOUNGE_LINE ? { x: x - LOUNGE_LINE, dy: TALL.loungeWall - WALL_BOTTOM } : { x, dy: 0 });

  /**
   * `pieces` along the wall's `stretches`: each wholly on one stays where
   * it is, and each the elevator, a doorway or the window has come over
   * goes to the nearest place clear of the others; with none, it's `away`
   * off the wall for now, never over another. What's moved, or away, comes
   * back once it's clear again: where it's kept doesn't change.
   */
  function fitWall(pieces, stretches) {
    const half = (piece) => wallWidthOf(piece.kind) / 2;
    const on = (piece, x = piece.x) => stretches.some(([from, to]) => x - half(piece) >= from && x + half(piece) <= to);
    const out = pieces.map((piece) => piece);
    const kept = pieces.filter((piece) => piece.kind === 'bare' || on(piece));
    const clear = (piece, x) => kept.every((other) => other.kind === 'bare' || Math.abs(other.x - x) >= half(piece) + half(other));
    pieces.map((piece, i) => ({ piece, i })).filter(({ piece }) => !kept.includes(piece)).sort((a, b) => a.piece.x - b.piece.x)
      .forEach(({ piece, i }) => {
        let x = null;
        for (let d = 0; d <= WALL_LENGTH && x === null; d++) {
          for (const at of [piece.x - d, piece.x + d]) if (x === null && on(piece, at) && clear(piece, at)) x = at;
        }
        out[i] = x === null ? { ...piece, away: true } : { ...piece, x };
        if (x !== null) kept.push(out[i]);
      });
    return out;
  }

  /** A room as the layout gives it: anything unknown or left out is as standard. */
  /**
   * The dress code: an outfit and colour for each size of model, and for
   * each agent while its model isn't known, and your own rules for telling
   * a model's size from its name. Outfits and colours are the team's
   * choices. The apps' Layout.swift and layout.go keep the same.
   */
  const DRESS_SIZES = ['small', 'medium', 'large', 'top'];
  const DRESS_AGENTS = ['claude', 'codex', 'gemini', 'opencode', 'grok'];
  /** The most rules a dress code keeps, and the most characters a rule's words can be. */
  const DRESS_RULE_LIMIT = 20;
  const DRESS_WORDS_LIMIT = 32;
  const AUTO_ATTIRE = { outfit: 'auto', colour: 'auto' };

  /** How many pets the office can have at once. */
  const PETS_MOST = 3;

  /** A dress code as given: anything unknown is Auto, and a rule that can't be read is left out. */
  function dressOf(given) {
    const raw = given && typeof given === 'object' && !Array.isArray(given) ? given : {};
    // Read only when there's something to read: this runs as the office loads, before the team's choices exist.
    const attire = (a) => (a && typeof a === 'object' ? {
      outfit: TEAM_CHOICES.outfit.includes(a.outfit) ? a.outfit : 'auto',
      colour: TEAM_CHOICES.colour.includes(a.colour) ? a.colour : 'auto',
    } : { ...AUTO_ATTIRE });
    const each = (keys, from) => Object.fromEntries(keys.map((key) =>
      [key, attire(from && typeof from === 'object' && Object.hasOwn(from, key) ? from[key] : null)]));
    const rules = (Array.isArray(raw.rules) ? raw.rules : [])
      .map((rule) => ({
        contains: rule && typeof rule.contains === 'string'
          ? [...rule.contains.replace(/[\x00-\x1f\x7f]/g, '').trim().toLowerCase()].slice(0, DRESS_WORDS_LIMIT).join('') : '',
        size: rule && rule.size,
      }))
      .filter((rule) => rule.contains && DRESS_SIZES.includes(rule.size))
      .slice(0, DRESS_RULE_LIMIT);
    return { sizes: each(DRESS_SIZES, raw.sizes), agents: each(DRESS_AGENTS, raw.agents), rules };
  }

  function roomOf(given) {
    const raw = given && typeof given === 'object' ? given : {};
    const room = {};
    for (const [part, choices] of Object.entries(ROOM_CHOICES)) room[part] = choices.includes(raw[part]) ? raw[part] : choices[0];
    room.wall = STANDARD_WALL.map((standard, i) => (Array.isArray(raw.wall) && WALL_CHOICES.includes(raw.wall[i]) ? raw.wall[i] : standard));
    room.team = teamOf(raw.team);
    room.dress = dressOf(raw.dress);
    room.plan = planOf(raw.plan);
    // In a style, the style furnishes it, from the standard.
    const style = ROOM_STYLES[room.preset];
    if (style) {
      for (const part of STYLED) {
        const standard = part === 'wall' ? [...STANDARD_WALL] : ROOM_CHOICES[part][0];
        room[part] = Object.hasOwn(style.room, part) ? structuredClone(style.room[part]) : standard;
      }
    }
    // The pets: up to PETS_MOST of them, each once, given as a list, or one by its id as before. In a style, the ones you've
    // picked take the place of its own; with none picked, it has its own.
    const picked = (Array.isArray(raw.pet) ? raw.pet : [raw.pet]).filter((kind, i, all) => kind !== 'none' && ROOM_CHOICES.pet.includes(kind) && all.indexOf(kind) === i).slice(0, PETS_MOST);
    room.pets = style && !picked.length ? (room.pet === 'none' ? [] : [room.pet]) : picked;
    room.pet = room.pets[0] || 'none';
    return room;
  }

