  /** `a` mixed `k` of the way to `b`. */
  const nbaMix = (a, b, k) => {
    const ch = (shift) => Math.round(((a >> shift) & 255) * (1 - k) + ((b >> shift) & 255) * k);
    return (ch(16) << 16) | (ch(8) << 8) | ch(0);
  };
  /** A team's wall paint: its main colour darkened into a wall, the second colour for the rail. */
