        for (const [bx, by] of [[-8, 7], [6, 6], [-7, 23], [7, 22]]) { dot(x + bx, by, Y); dot(x + bx + 1, by + 1, Y); dot(x + bx, by + 2, Y); dot(x + bx + 1, by + 3, Y); }
        // The ears, leaning out, black at the tips
