          dot(x + 4, y + 3, 0xeae6dc); fill(x + 3, y + 4, 3, 1, 0xeae6dc); disc(x + 8, y + 5, 1, 0xf2d35b); fill(x + 3, y + 6, 2, 1, 0x4ad4e8);
