          fill(x - 2, y - 1, 3, 1, PALETTE.leaf); dot(x - 1, y - 2, PALETTE.leafDark); dot(x + 13, y + 2 + sway, PALETTE.leaf); fill(x + 13, y + 5, 2, 1, PALETTE.leafDark); dot(x + 14 + sway, y + 7, PALETTE.leaf);
