          dot(x - 1, y - 3, twig); dot(x - 1, y - 1, twigDark); dot(x + 13, y - 3, twig); dot(x + 13, y - 2, twigLight); dot(x + 12, y - 4, twig); dot(x + 1, y - 4, twigLight);
