    /**
     * A watch party: a big TV on a low stand, a game on it. Two teams of little players, teal and orange, run up and down
     * a court between the hoops after the ball, the crowd's colours flickering behind; a score bug in its corner, like the
     * wall's, ticks a basket up now and then, flashing as it does. The TV lights the corner at night.
     */
    function drawWatchParty() {
      const wood = 0x5a3b25, top = 0x7a5232, bezel = 0x1a1a1f;
      fill(253, 93, 50, 1, SHADOW);
      // The stand: two doors, little feet
      fill(256, 81, 44, 2, top); fill(256, 81, 44, 1, 0x9a6a42);
      fill(257, 83, 42, 9, wood);
      fill(277, 84, 1, 7, 0x3a2616); fill(258, 84, 18, 7, 0x6a4530); fill(279, 84, 19, 7, 0x6a4530);
      dot(274, 87, PALETTE.brass); dot(281, 87, PALETTE.brass);
      for (const fx of [258, 297]) fill(fx, 92, 2, 1, 0x3a2616);
      // The TV on its foot
      fill(274, 78, 8, 3, 0x2a2a2e);
      fill(254, 51, 48, 28, bezel); fill(254, 51, 48, 1, 0x3a3a40);
      const L = 256, T = 53, W = 44, H = 24;
      if (isNight) glowAt(278, 66, 30, 20, 0x9ac8ff, 0.06);
      // The crowd, in the stands
      fill(L, T, W, 6, 0x2a2d38);
      for (let k = 0; k < 22; k++) {
        const cx = L + 1 + k * 2, cy = T + 1 + ((k * 5) % 3) + (k % 2) * 2;
        dot(cx, cy, k % 3 === 0 ? SIDE_TEAL : k % 3 === 1 ? SIDE_ORANGE : 0xeae6dc, (Math.floor(now * 2 + k * 0.7) % 4) ? 0.7 : 1);
      }
      // The court: boards, the half-way line, its circle, a key and a hoop at each end
      fill(L, T + 6, W, H - 6, 0xd9a35e);
      for (let r = T + 8; r < T + H; r += 3) fill(L, r, W, 1, 0xcc9450);
      fill(L, T + 6, W, 1, 0xf4f1ea);
      fill(L + 21, T + 6, 1, H - 6, 0xf4f1ea);
      for (let k = 0; k < 16; k++) {
        const a = (k / 16) * Math.PI * 2;
        dot(L + 21 + Math.round(Math.cos(a) * 4), T + 15 + Math.round(Math.sin(a) * 3), 0xf4f1ea);
      }
      for (const [kx, c] of [[L, SIDE_TEAL], [L + W - 7, SIDE_ORANGE]]) fill(kx, T + 11, 7, 8, c, 0.85);
      for (const [bx, rx] of [[L + 1, L + 2], [L + W - 2, L + W - 5]]) {
        fill(bx, T + 7, 1, 6, 0xf4f1ea); fill(rx, T + 11, 3, 1, 0xe0602a);
      }
      // The players: up the court and back, each a little behind the one before, the ball with whoever leads
      const run = (now % 16) / 16, lead = Math.sin(run * Math.PI * 2);
      for (let i = 0; i < 6; i++) {
        const px = L + 22 + Math.round(Math.sin(run * Math.PI * 2 - i * 0.35) * 15) + (i % 3) * 2 - 2, py = T + 11 + ((i * 4) % 9);
        const c = i % 2 ? SIDE_ORANGE : SIDE_TEAL, step = Math.floor(now * 6 + i) % 2;
        fill(px, py - 2, 2, 2, 0x8a5a3a); fill(px, py, 2, 3, c); dot(px + step, py + 3, 0x3a2a22);
      }
      const bx = L + 22 + Math.round(lead * 15) + 3, bounce = Math.abs(Math.sin(now * 5)) * 2;
      dot(bx, T + 13 - Math.round(bounce), 0xe0602a);
      // The score bug, bottom left, in the wall's: a black bar, a tab of each side's colour, each side's score
      const tick = Math.floor(now / 11), flash = now % 11 < 0.8 && Math.floor(now * 6) % 2;
      fill(L + 1, T + H - 7, 30, 6, 0x0e0e0e); fill(L + 1, T + H - 7, 30, 1, 0x333333);
      fill(L + 2, T + H - 5, 2, 3, SIDE_TEAL); fill(L + 16, T + H - 5, 2, 3, SIDE_ORANGE);
      const home = 60 + Math.floor((tick * 5) / 3) % 40, away = 58 + Math.floor((tick * 4) / 3) % 40;
      pixelText(String(home), L + 5, T + H - 6, flash && tick % 2 === 0 ? 0xffd04a : 0xf5f5f5, false);
      pixelText(String(away), L + 19, T + H - 6, flash && tick % 2 === 1 ? 0xffd04a : 0xf5f5f5, false);
      // The screen's sheen
      fill(L, T, 1, H, WHITE, 0.08);
    }

    /** A bowl of popcorn on the floor before the TV; now and then a piece hops out and drops back in. */
    function drawPopcorn() {
      const cx = 277;
      fill(cx - 5, 98, 11, 1, SHADOW);
      for (const [dx, dy] of [[-3, 92], [-1, 91], [1, 91], [3, 92], [-2, 93], [0, 92], [2, 93], [-4, 93], [4, 93]]) {
        dot(cx + dx, dy, (dx + dy) % 3 ? 0xfff2cc : 0xf2d38a);
      }
      fill(cx - 5, 94, 11, 2, SIDE_TEAL); fill(cx - 4, 96, 9, 1, SIDE_TEAL_DARK); fill(cx - 3, 97, 7, 1, SIDE_TEAL_DARK);
      fill(cx - 5, 94, 11, 1, 0x5ac0b6);
      const t = (now + 4) % 9;
      if (t < 0.7) dot(cx + 1 + Math.round(t * 3), 90 - Math.round(Math.sin((t / 0.7) * Math.PI) * 4), 0xfff2cc);
    }

    /** A rack of basketballs on wheels, three to a shelf. */
    function drawBallRack() { drawRack(false); }
    /** The same, a jack-o'-lantern in the top shelf's middle. */
    function drawPumpkinRack() { drawRack(true); }

    /** A rack of basketballs on wheels, three to a shelf, a jack-o'-lantern in the top one's middle when it has a `pumpkin`. */
    function drawRack(pumpkin) {
      const steel = 0x5a5f6c, light = 0x8a8f9c;
      fill(262, 93, 34, 1, SHADOW);
      for (const px of [263, 293]) { fill(px, 66, 2, 26, steel); fill(px, 66, 1, 26, light); }
      for (const [rail, i] of [[75, 0], [83, 1], [91, 2]]) {
        fill(263, rail, 32, 1, steel);
        fill(263, rail, 32, 1, light, 0.5);
        [270, 279, 288].forEach((bx, k) => {
          if (pumpkin && i === 0 && k === 1) drawPumpkin(bx, rail, false, 0, candlelight(5));
          else drawBall(bx, rail - 4, 3);
        });
      }
      for (const wx of [264, 294]) { fill(wx - 1, 92, 3, 2, 0x2a2a2e); dot(wx, 92, 0x6a6e76); }
    }

    /** Bubbler jukebox. A chrome arch round a glowing tube, bubbles rising in the side tubes. Playing, the tube runs round the colours and the bubbles rise faster. */
    function drawBubbler() {
      // Playing: the computer's music, with the control on, or someone at it
      const playing = frame.music?.playing === true || atCorner(0);
      const wood = 0x6b3a22, chrome = 0xc8cdd6, cx = 274;
      const tube = playing ? lighter(rainbow((now * 0.12) % 1)) : 0xb0703a;
      fill(261, 88, 27, 1, SHADOW);
      for (let row = 54; row <= 66; row++) {
        const d = 66 - row, half = (r) => Math.round(Math.sqrt(Math.max(0, r * r - d * d)));
        fill(cx - half(12.5), row, half(12.5) * 2 + 1, 1, chrome);
        if (row >= 56) fill(cx - half(10.5), row, half(10.5) * 2 + 1, 1, tube);
        if (row >= 58) fill(cx - half(8), row, half(8) * 2 + 1, 1, 0x2a1a2a);
      }
      fill(cx - 4, 60, 1, 4, WHITE, 0.3); dot(cx - 3, 59, WHITE, 0.3);
      // the pilasters, a bubble tube in each
      for (const px of [262, 282]) {
        fill(px, 66, 5, 20, wood); fill(px, 66, 1, 20, 0x8a4a2e);
        fill(px + 1, 67, 3, 18, playing ? 0xe0507a : 0x8a3a52);
        for (let k = 0; k < 4; k++) {
          const by = playing ? 84 - ((now * 7 + k * 4.6 + px) % 17) : 70 + k * 4;
          dot(px + 1 + (k % 2) * 2, Math.round(by), WHITE, playing ? 0.85 : 0.4);
        }
      }
      fill(267, 66, 15, 20, wood);
      // the record turning behind glass, the buttons, the grille
      fill(268, 67, 13, 6, PALETTE.doorway); fill(268, 67, 13, 1, WHITE, 0.2);
      fill(271, 69, 7, 3, 0x1a1a1f); dot(274, 70, 0xd96a5a);
      if (playing) dot(271 + (Math.floor(now * 8) % 2) * 6, 70, 0x5a5a66);
      fill(268, 74, 13, 2, chrome); for (let k = 0; k < 6; k++) dot(269 + k * 2, 74, playing && k === 3 ? 0x6fd36f : 0x8a8f9c);
      fill(268, 77, 13, 8, playing ? 0xf0a040 : 0x8a5a2a);
      for (let row = 77; row < 85; row += 2) fill(268, row, 13, 1, chrome);
      fill(262, 85, 25, 1, chrome); fill(262, 86, 25, 2, 0x4a2618);
      if (playing) notes(266, 52, 7);
    }

    /** Neon jukebox. A black cabinet outlined in neon, an equaliser in its window. Playing, the neon pulses on the beat and the bars dance. */
    function drawNeonJukebox() {
      // Playing: the computer's music, with the control on, or someone at it
      const playing = frame.music?.playing === true || atCorner(0);
      const body = 0x14161b, pink = 0xff5aa8, cyan = 0x4ad4e8;
      const pulse = playing ? (onBeat() ? 1 : 0.65) : 0.3;
      fill(263, 88, 23, 1, SHADOW);
      if (playing) fill(261, 52, 27, 37, pink, 0.05 * pulse);
      fill(267, 56, 15, 1, body); fill(265, 57, 19, 31, body);
      const tube = (x, y, c) => { dot(x, y, playing ? lighter(c) : shaded(c, 0.55), playing ? 1 : 0.8); if (playing) fill(x - 1, y - 1, 3, 3, c, 0.07 * pulse); };
      for (let x = 267; x <= 281; x++) tube(x, 57, pink);
      for (let y = 58; y <= 72; y++) { tube(265, y, pink); tube(283, y, pink); }
      fill(268, 60, 13, 10, PALETTE.doorway);
      for (let k = 0; k < 6; k++) {
        const h = playing ? 1 + Math.round(3.5 * (1 + Math.sin(now * (4 + k * 1.3) + k))) : 1;
        for (let r = 0; r < h; r++) dot(269 + k * 2, 68 - r, r > 4 ? pink : r > 2 ? 0xf2d35b : cyan);
      }
      for (let x = 267; x <= 281; x++) { tube(x, 74, cyan); tube(x, 86, cyan); }
      for (let y = 75; y <= 85; y++) { tube(267, y, cyan); tube(281, y, cyan); }
      for (const sx of [271, 278]) {
        disc(sx, 80, 2.5, 0x3a3d47); disc(sx, 80, playing && onBeat() ? 1.5 : 1, 0x1d1f25); dot(sx, 80, 0x6a7080);
      }
      if (playing) notes(268, 53);
    }

