      fill(266, 66, 17, 1, 0x5a5f6c); fill(266, 67, 1, 2, 0x5a5f6c); fill(282, 67, 1, 2, 0x5a5f6c);
      line(284, 68, 290, 58, 0x9aa0a6); dot(290, 57, 0xc8cdd6);
