    /** A potter's kick wheel with a stool, a water bucket, and two finished pots on a shelf; every 30 s the wheel spins (stepped streaks) and the terracotta clay rises through lump, cone, cylinder and pot over four rounds, then is squashed and starts again. Someone sitting at it throws, twice as fast. */
    function drawPotterywheel() {
      const someone = atCorner(0), cx = 277;
      const clay = 0xb8643a, clayLight = 0xd88858, clayDark = 0x8a4428;
      const wood = 0x8a5a32, woodLight = 0xa8703e, woodDark = 0x5a3b25, steel = 0x6e727c, steelLight = 0xa8adb6, steelDark = 0x4a4e58;
      fill(253, 96, 50, 1, SHADOW);
      // The shelf on the wall with two finished pots
      fill(249, 62, 21, 2, wood); fill(249, 62, 21, 1, woodLight); fill(250, 64, 2, 2, woodDark); fill(267, 64, 2, 2, woodDark);
      fill(252, 55, 6, 7, clay); fill(251, 57, 8, 4, clay); fill(252, 55, 1, 7, clayLight); fill(258, 57, 1, 5, clayDark); fill(253, 54, 4, 1, clayDark);
      fill(261, 56, 6, 6, 0xe8e0cc); fill(260, 58, 8, 3, 0xe8e0cc); fill(261, 56, 1, 6, WHITE, 0.6); fill(267, 58, 1, 4, 0xb8b0a0); fill(262, 55, 4, 1, 0xb8b0a0); fill(261, 59, 6, 1, 0x4c8bf5);
      // The stool: a round seat on three legs
      fill(258, 88, 11, 2, wood); fill(258, 88, 11, 1, woodLight); fill(259, 90, 2, 6, woodDark); fill(266, 90, 2, 6, woodDark); fill(262, 90, 1, 6, woodDark, 0.7);
      // The wheel frame: two legs, a shaft, the flywheel low down and the head on top
      fill(271, 82, 2, 14, wood); fill(271, 82, 1, 14, woodLight); fill(282, 82, 2, 14, wood); fill(283, 82, 1, 14, woodDark); fill(271, 95, 13, 1, woodDark);
      fill(cx, 82, 1, 8, steelDark);
      const spinning = someone || (now + 4.3) % 30 < 4, k = someone ? 10 : 6, st = Math.floor(now * k);
      // The heavy kick wheel seen edge-on, a mark sliding across its rim while it turns
      fill(cx - 5, 90, 11, 3, steel); fill(cx - 5, 90, 11, 1, steelLight); fill(cx - 5, 92, 11, 1, steelDark);
      if (spinning) { const m = st % 9; dot(cx - 4 + m, 91, steelDark); dot(cx - 4 + ((m + 4) % 9), 91, steelLight, 0.8); } else dot(cx + 2, 91, steelDark);
      fill(cx - 6, 80, 13, 2, steel); fill(cx - 6, 80, 13, 1, steelLight);
      // The clay: four shapes over a 2-minute cycle (twice as fast while someone throws), squashed at the end
      const c = (now * (someone ? 2 : 1) + 11) % 120, stage = c >= 116 ? 0 : Math.floor(c / 30);
      const rows = [[[5, 1], [7, 3]], [[1, 1], [3, 1], [5, 2], [7, 2]], [[6, 1], [6, 1], [6, 2], [6, 2], [6, 2]], [[4, 1], [5, 1], [7, 2], [8, 2], [6, 1], [4, 1]]][stage];
      let y = 80;
      const flat = rows.slice().reverse();   // built from the bottom up
      flat.forEach(([w, h]) => { y -= h; fill(cx - Math.floor(w / 2), y, w, h, clay); fill(cx - Math.floor(w / 2), y, 1, h, clayLight); fill(cx - Math.floor(w / 2) + w - 1, y, 1, h, clayDark); });
      // Streak marks sliding round the clay while it spins
      if (spinning) for (let yy = y + 1; yy < 80; yy += 2) { const ph = (st + yy) % 3; dot(cx - 2 + ph, yy, clayLight, 0.9); }
      if (someone && stage > 0) dot(cx + 3, y + 1, 0x4c8bf5, 0.6);
      // The water bucket with a ripple
      fill(291, 86, 9, 9, 0x5a7a9a); fill(291, 86, 1, 9, 0x7a9aba); fill(299, 86, 1, 9, 0x3a5a7a); fill(291, 94, 9, 1, 0x3a5a7a);
      fill(292, 86, 7, 2, 0x8ab8dc); dot(293 + (Math.floor(now * 0.5) % 4), 87, WHITE, 0.6); fill(291, 90, 9, 1, 0x3a5a7a, 0.6);
      dot(291, 85, 0x7a7e88); dot(292, 84, 0x7a7e88); fill(293, 83, 5, 1, 0x7a7e88); dot(298, 84, 0x7a7e88); dot(299, 85, 0x7a7e88);   // the handle
    }

    /** A vintage reel-to-reel film projector on a tripod with two big reels, a lens and a film can on the floor; while someone watches, or for a few seconds every 40 s, the reels turn in steps and a faint dusty beam fans out of the lens to the left, showing more at night. */
    function drawProjector() {
      const someone = atCorner(0), on = someone || (now + 9) % 40 < 5;
      const metal = 0x5a7a6a, metalLight = 0x7a9c8a, metalDark = 0x3a5444, steelDark = 0x4a4e58, steelLight = 0xa8adb6, reelC = 0xc8ccd4;
      fill(266, 95, 40, 1, SHADOW);
      // The tripod: three legs spreading to the floor
      line(288, 81, 279, 94, 0x6a4a2e); line(289, 81, 298, 94, 0x6a4a2e); fill(288, 81, 1, 13, 0x8a6440);
      dot(279, 94, steelDark); dot(298, 94, steelDark); dot(288, 94, steelDark);
      // The beam, fanning left from the lens (behind the projector so the lens sits on top)
      if (on) {
        for (let bx = 250; bx < 272; bx++) {
          const half = Math.round((272 - bx) * 0.32) + 1;
          fill(bx, 75 - half, 1, half * 2, 0xfff4d0, isNight ? 0.13 : 0.07);
        }
        for (let k = 0; k < 5; k++) {
          const px = 252 + Math.floor(hash(k, 7) * 18), py = 75 + Math.round((hash(k, 3) - 0.5) * (272 - px) * 0.5);
          if ((Math.floor(now * 3) + k) % 4 !== 0) dot(px, py, WHITE, isNight ? 0.6 : 0.35);
        }
      }
      // The film can on the floor, and the body of the projector
      fill(299, 90, 8, 5, 0x8a8e98); fill(299, 90, 8, 1, steelLight); fill(299, 90, 1, 5, steelLight); fill(306, 90, 1, 5, steelDark); fill(299, 94, 8, 1, steelDark); fill(300, 92, 6, 1, 0xd8402a);
      fill(280, 70, 17, 11, metal); fill(280, 70, 17, 1, metalLight); fill(280, 70, 1, 11, metalLight); fill(296, 70, 1, 11, metalDark); fill(280, 80, 17, 1, metalDark);
      dot(284, 77, 0xd8402a); dot(287, 77, 0xe8c878); fill(290, 74, 4, 4, metalDark);
      // The lens barrel
      fill(273, 73, 7, 5, steelDark); fill(273, 73, 7, 1, steelLight); fill(272, 74, 1, 3, 0x9ac8e8); dot(272, 74, WHITE, 0.8); fill(276, 73, 1, 5, steelLight, 0.5);
      // The reels on their arms, spokes stepping round while it runs
      fill(283, 63, 1, 7, steelDark); fill(293, 60, 1, 10, steelDark);
      const st = on ? Math.floor(now * 5) : 0;
      [[283, 62, 6], [293, 58, 5]].forEach(([cx, cy, r], n) => {
        disc(cx, cy, r, reelC); disc(cx, cy, r - 1.4, 0x2a2e38, 0.55); ring(cx, cy, r, 0xe8ecf2, 0.8);
        for (let k = 0; k < 3; k++) { const a = ((st + n) % 6) * (Math.PI / 3) + (k * Math.PI * 2) / 3; line(cx, cy, cx + Math.round(Math.cos(a) * (r - 1)), cy + Math.round(Math.sin(a) * (r - 1)), reelC); }
        disc(cx, cy, 1.2, steelDark);
      });
      line(284, 68, 289, 70, 0x2a2e38); line(293, 63, 294, 70, 0x2a2e38, 0.8);
      if (on && isNight) glowLate(() => glowAt(272, 75, 3, 3, 0xfff0c0, 0.25));
    }

    /** A garden bird-feeder pole in a pot of grass: a hanging seed tube, a little roof and a tray; every 30 s a sparrow flutters down onto the tray, pecks three times and flies off, and someone standing at it tops up the seed. */
    function drawBirdfeeder() {
      const someone = atCorner(0);
      const pole = 0x6e727c, poleLight = 0xa8adb6, poleDark = 0x4a4e58;
      const roof = 0xb8483a, roofLight = 0xd8685a, roofDark = 0x8a2e26, wood = 0x8a5a32, woodLight = 0xa8703e, woodDark = 0x5a3b25;
      const seed = 0xd8b048, seedDark = 0xa8822c, pot = PALETTE.pot, potLight = 0xc07a52, potDark = 0x7a452a;
      const cx = 277;
      fill(266, 94, 22, 1, SHADOW);
      // The pole, with a hook arm at the top for the tube
      fill(cx, 54, 1, 38, pole); fill(cx, 54, 1, 38, poleLight, 0.0); dot(cx, 60, poleLight); fill(cx - 1, 74, 3, 1, poleDark);
      fill(cx, 52, 5, 1, pole); fill(cx + 4, 52, 1, 3, pole); dot(cx, 52, poleLight);
      // The pot of grass at the foot
      fill(cx - 6, 86, 13, 8, pot); fill(cx - 6, 86, 1, 8, potLight); fill(cx + 6, 86, 1, 8, potDark); fill(cx - 7, 85, 15, 1, potLight); fill(cx - 6, 92, 13, 2, potDark);
      for (const [gx, gh, c] of [[-6, 3, 0x4f9a5a], [-4, 5, 0x6cb86a], [-2, 3, 0x3b7a46], [0, 4, 0x4f9a5a], [2, 6, 0x6cb86a], [4, 3, 0x3b7a46], [6, 4, 0x4f9a5a]]) fill(cx + gx, 85 - gh, 1, gh, c);
      // The hanging seed tube: glass with seeds in it (fuller just after being topped up)
      const level = someone ? 11 : 8;
      fill(cx - 3 + 5, 55, 1, 3, pole);
      fill(cx + 2, 58, 6, 14, 0xdff0f6, 0.4); fill(cx + 2, 58, 1, 14, WHITE, 0.45); fill(cx + 7, 58, 1, 14, 0xa8d4ea, 0.6);
      fill(cx + 3, 71 - level, 4, level, seed); fill(cx + 3, 71 - level, 4, 1, 0xf2d070); dot(cx + 5, 68, seedDark); dot(cx + 4, 64, seedDark); dot(cx + 6, 66, seedDark);
      dot(cx + 3, 60, WHITE, 0.9);
      // The little roof over it
      fill(cx + 3, 54, 4, 1, roof); fill(cx + 1, 55, 8, 1, roof); fill(cx, 56, 10, 1, roofLight); fill(cx, 57, 10, 1, roofDark);
      // The tray under the tube
      fill(cx - 1, 72, 12, 2, wood); fill(cx - 1, 72, 12, 1, woodLight); fill(cx + 10, 72, 1, 2, woodDark); fill(cx - 1, 73, 12, 1, woodDark);
      dot(cx + 2, 71, seed); dot(cx + 8, 71, seed); dot(cx + 5, 71, seedDark);
      // Seed pouring in from above while someone tops it up
      if (someone) { const k = Math.floor(now * 8) % 4; dot(cx + 4, 50 + k * 2, seed); dot(cx + 6, 51 + k * 2, seedDark); fill(cx + 3, 49, 5, 1, seed, 0.6); }
      // The sparrow: every 30 s it flutters down onto the tray, pecks three times and flies off
      const t = (now + 11) % 30;
      if (t < 5.4) {
        const brown = 0x8a6a4a, brownDark = 0x5a4430, belly = 0xe0d4bc, cap = 0x9a5a38;
        let sx, sy, perched = false, flap = false;
        if (t < 1.4) { const k = t / 1.4; sx = Math.round(298 - k * 17); sy = Math.round(50 + k * 17 + Math.sin(t * 14) * 1.5); flap = true; }
        else if (t < 3.8) { sx = 281; sy = 69; perched = true; }
        else { const k = (t - 3.8) / 1.6; sx = Math.round(281 - k * 22); sy = Math.round(69 - k * 22 + Math.sin(t * 14) * 1.5); flap = true; }
        const peck = perched && t >= 1.8 && t < 3.6 ? Math.floor((t - 1.8) * 3.3) % 2 : 0;
        const dir = t < 3.8 ? -1 : -1;
        fill(sx - 1, sy, 5, 3, brown); fill(sx - 1, sy + 2, 4, 1, belly); fill(sx + 3, sy, 1, 2, brownDark);
        fill(sx - 2 + (flap ? 0 : 0), sy + 1, 1, 1, brownDark);
        fill(sx - 3, sy - 1 + peck * 2, 3, 2, cap); dot(sx - 4, sy + peck * 2, 0xf2c030); dot(sx - 3, sy + peck * 2, PALETTE.eye);
        if (flap) { fill(sx, sy - 2 - (Math.floor(now * 12) % 2), 2, 2, brownDark); } else dot(sx + 1, sy + 1, brownDark);
        if (perched) { dot(sx, sy + 3, 0xd08a40); dot(sx + 2, sy + 3, 0xd08a40); }
      }
    }

    /** A tall glass vivarium on a low wooden cabinet: a branch, broad leaves, moss on the floor and a bright green gecko clinging to the glass; every 40 s a fine mist sprays from the top and the gecko licks its eye or moves to a new spot, and a warm basking lamp glows at night. */
