      line(268, 76, 276, 66, branch); line(276, 66, 285, 60, branch); line(276, 66, 280, 71, branch); line(268, 77, 268, 74, branch);
      for (const [lx, ly] of [[266, 66], [270, 62], [281, 55], [284, 62], [278, 71], [271, 71]]) {
        fill(lx, ly, 5, 2, leaf); fill(lx + 1, ly - 1, 3, 1, leafLight); fill(lx + 1, ly + 2, 3, 1, leafDark); dot(lx + 2, ly, leafLight);
      }
      // The warm basking lamp under the roof, shining brighter at night
