      if (isNight) glowLate(() => { glowAt(277, 56, 8, 7, 0xffb050, 0.2); fill(276, 52, 3, 1, 0xfff4c0); });
      else glowAt(277, 55, 6, 5, 0xffd890, 0.06);
      // The gecko: clings to the glass in one of three spots, licking its eye or hopping to a new one every 40 s
      const tt = now + 7, cycle = Math.floor(tt / 40), t = tt % 40;
      const spots = [[285, 57], [267, 62], [283, 68]], count = Math.floor((cycle + (t > 5.2 ? 1 : 0)) / 2);
      const [gx, gy] = spots[(Math.imul(count + 5, 2654435761) >>> 27) % 3], lick = cycle % 2 === 0 && t >= 4.2 && t < 5.4 && Math.floor(t * 5) % 2 === 0;
      fill(gx, gy, 3, 6, gecko); fill(gx, gy, 1, 6, geckoLight); fill(gx + 2, gy, 1, 6, geckoDark); fill(gx, gy - 2, 3, 2, gecko); dot(gx + 1, gy - 3, geckoLight);
      dot(gx - 1, gy - 1, geckoDark); dot(gx + 3, gy - 1, geckoDark); dot(gx - 1, gy + 4, geckoDark); dot(gx + 3, gy + 4, geckoDark);
      dot(gx + 1, gy + 6, geckoDark); dot(gx + 2, gy + 7, geckoDark);
      dot(gx, gy - 2, 0xf2c030); dot(gx + 2, gy - 2, 0xf2c030); dot(gx + 2, gy - 2, PALETTE.eye, 0.0); dot(gx + 1, gy, 0xf2f08a, 0.7);
      if (lick) dot(gx + 3, gy - 2, 0xf28fb0);
      // The glass front, frame and a glint
