      fill(left - 1, top - 1, right - left + 2, 1, steel); fill(left - 1, floor, right - left + 2, 1, steel); fill(left - 1, top, 1, floor - top, steel); fill(right, top, 1, floor - top, steel);
      fill(left - 1, top - 1, right - left + 2, 1, steelLight, 0.0); dot(left - 1, top - 1, steelLight);
