      fill(250, 93, 56, 1, SHADOW);
      // The hole and its glow
      for (let k = 0; k < 7; k++) fill(258 + k, 84 - k, 40 - k * 2, 1, 0x1a0e24);
      fill(258, 84, 40, 8, 0x1a0e24);
      glowAt(278, 84, 18, 6, glow, isNight ? 0.25 : 0.15);
      // The Baron: a thick spined neck rising, the head at its top
      const hy = 80 - rise;
      if (rise > 0) {
        fill(271, hy + 4, 14, 84 - hy - 4, P); fill(271, hy + 4, 2, 84 - hy - 4, PL); fill(283, hy + 4, 2, 84 - hy - 4, PD);
        for (let sy = hy + 6; sy < 82; sy += 4) { fill(269, sy, 2, 2, PD); fill(285, sy, 2, 2, PD); }
      }
