      fill(270, hy + 2, 16, 3, P); fill(271, hy + 5, 14, 1, PD); fill(270, hy + 2, 1, 3, PL);
      for (const [hx, d] of [[264, -1], [290, 1]]) { fill(hx, hy - 7, 3, 5, PD); fill(hx + d, hy - 10, 2, 3, PD); dot(hx + d + (d > 0 ? 1 : 0), hy - 11, PL); dot(hx + 1, hy - 7, PL); }
      for (let k = 0; k < 5; k++) { fill(270 + k * 4, hy - 7 + (k % 2), 2, 3 - (k % 2), PD); dot(270 + k * 4, hy - 7 + (k % 2), PL); }
      fill(271, hy - 2, 4, 1, eye); fill(272, hy - 1, 3, 1, eye); fill(281, hy - 2, 4, 1, eye); fill(281, hy - 1, 3, 1, eye); dot(272, hy - 1, WHITE, 0.8); dot(283, hy - 1, WHITE, 0.8);
      const roar = rise > 20 && Math.floor(now * 3) % 2;
      fill(273, hy + 2, 10, roar ? 3 : 1, 0x2a0a1a); dot(274, hy + 3, 0xf0e8d0); dot(281, hy + 3, 0xf0e8d0); if (roar) { for (let k = 0; k < 4; k++) dot(274 + k * 2, hy + 2, 0xf0e8d0); }
      // The rocks round the rim, in front of the Baron
