      for (const [rx, ry, rw, rh] of rocks) { fill(rx, ry, rw, rh, 0x6a6a72); fill(rx, ry, rw, 1, 0x9a9aa2); fill(rx, ry, 1, rh, 0x8a8a92); fill(rx + rw - 1, ry + 1, 1, rh - 1, 0x4a4a52); }
      if (isNight) glowLate(() => { glowAt(278, hy, 10, 4, eye, 0.12); dot(272, hy - 1, 0xfaffb0); dot(283, hy - 1, 0xfaffb0); glowAt(278, 86, 16, 5, glow, 0.12); });
