    /**
     * A Cryptarch's decoder: a white and gold console on a plinth with a purple engram floating over it in turning rings
     * of light. Every 20 s, or with someone handing one in, it decodes: the engram spins faster, flares, bursts into
     * gold for a moment and settles back to purple. It glows at night.
     */
    function drawDestinycryptarch() {
      const someone = atCorner(0), period = someone ? 8 : 20, t = (now + 4) % period, decoding = t < 3, burst = t >= 2.4 && t < 3;
      fill(254, 93, 48, 1, SHADOW);
      // The plinth and the console with its screens
      fill(258, 80, 40, 13, DST_WHITE); fill(258, 80, 40, 1, WHITE); fill(258, 80, 1, 13, WHITE); fill(297, 81, 1, 12, 0xb8bcc4); fill(258, 86, 40, 1, DST_GOLD);
      fill(262, 72, 32, 8, 0xd8dce0); fill(262, 72, 32, 1, DST_GOLD);
      for (const sx of [264, 278]) { fill(sx, 74, 12, 4, 0x0e1a2a); for (let k = 0; k < 4; k++) dot(sx + 1 + ((Math.floor(now * 4) + k * 3) % 10), 75 + (k % 2) * 2, DST_TEAL); }
      // The rings and the engram
      const spin = now * (decoding ? 8 : 1.5), c = burst ? DST_EXOTIC : DST_LEGEND;
      for (const [rx, ry, sp] of [[12, 3, 1], [9, 5, -1.3]]) { ellipseRing(278, 58, rx, ry, c, 0.35); const a = spin * sp * 0.4; dot(278 + Math.round(Math.cos(a) * rx), 58 + Math.round(Math.sin(a) * ry), WHITE); }
      fill(277, 66, 3, 6, 0xb8bcc4); fill(277, 66, 1, 6, WHITE);
      engram(278, 58, 13, c, spin);
      if (decoding) glowAt(278, 58, 10, 10, c, burst ? 0.4 : 0.15);
      if (burst) for (let k = 0; k < 8; k++) { const a = k * Math.PI / 4, r = 6 + (t - 2.4) * 20; dot(278 + Math.round(Math.cos(a) * r), 58 + Math.round(Math.sin(a) * r), DST_EXOTIC); }
      if (isNight) glowLate(() => { glowAt(278, 58, 10, 9, c, 0.2); glowAt(278, 76, 14, 4, DST_TEAL, 0.1); });
    }

