    /**
     * Stained glass, `w` wide and `h` tall from (x0, y0): small diamond panes of ruby, sapphire, emerald, amber and violet
     * between dark lead lines, no figures; `a` is how strongly it shines, and `rowWidth(row)` narrows rows for an arched top.
     */
    function chapelGlass(x0, y0, w, h, a, rowWidth = () => w) {
      const glass = [0xc8303a, 0x2f5fb0, 0x3a9a5a, 0xf2b030, 0x7a4aa8, 0x2f5fb0];
      for (let r = 0; r < h; r++) {
        const rw = rowWidth(r), off = (w - rw) >> 1;
        for (let c = off; c < off + rw; c++) {
          const u = c + r, v = c - r + 60;
          if (u % 3 === 0 || v % 3 === 0) dot(x0 + c, y0 + r, 0x2a2a30);
          else dot(x0 + c, y0 + r, glass[(Math.floor(u / 3) * 7 + Math.floor(v / 3) * 3) % glass.length], a);
        }
      }
    }

