      const sw = (now + 2) % 16 < 1.5 ? [0, 1, 0, -1][Math.floor(now * 4) % 4] : 0;
      fill(258 + sw, 45, 1, 2, iron); fill(270 + sw, 45, 1, 2, iron);
      fill(256 + sw, 47, 17, 11, 0x6a4a2a); fill(256 + sw, 47, 17, 1, 0x8a6440); fill(257 + sw, 48, 15, 9, 0x2a3a2a);
      const W = 0xf2f0ea, hx = 262 + sw;
      fill(hx, 52, 5, 2, W); fill(hx + 4, 49, 2, 3, W); dot(hx + 5, 48, W); line(hx, 54, hx - 1, 56, W); line(hx + 4, 54, hx + 5, 56, W); line(hx + 4, 51, hx + 6, 53, W); dot(hx - 1, 52, W);
      // The barrel rack behind the bar
