      for (let k = 0; k < 4; k++) { const on = someone ? true : (Math.floor(now * 2) + k) % 3 === 0; dot(298 + (k % 2) * 4, 65 + Math.floor(k / 2) * 3, on ? 0x5aff7a : 0x2a4a2a); }
      fill(298, 72, 6, 3, 0x1a2a1a); fill(298, 73, Math.floor(now * (someone ? 3 : 1)) % 6 + 1, 1, 0x5aff7a);
      // Steam venting from the lid
