      for (let k = 0; k < 40; k++) { const lx = 258 + k, h = 3 + Math.round(Math.sin(k * 0.35) * 2) + (k > 30 ? -1 : 0); fill(lx, 74 - Math.floor(h / 2), 1, h, k < 8 ? snow : (k % 5 ? land : landDark)); }
      dot(266, 73, 0x8a7a5a); dot(280, 74, 0x8a7a5a); fill(286, 73, 2, 2, 0x8a5a3a);
