    /**
     * Shai-Hulud: the front of a great sandworm rearing out of a dune in the lounge, its ringed sand-coloured body curving up,
     * its huge round maw ringed with crystal teeth glowing orange inside. Sand pours from its rings, and every 15 s the maw
     * flexes open wider; with someone standing before it, it rises higher. Its throat glows at night.
     */
    function drawDuneworm() {
      const skin = 0xb8946a, skinLight = 0xd8b488, skinDark = 0x8a6a48, sand = 0xd8a868, sandDark = 0xb8884e, throat = 0xe86a2a, tooth = 0xf2ece0;
      const someone = atCorner(0), t = (now + 5) % 15, wide = t < 2 ? Math.sin(t / 2 * Math.PI) : 0, rise = someone ? 4 : 0;
      fill(246, 95, 62, 1, SHADOW);
      // The body curving up out of the sand
      for (let r = 0; r < 40; r++) {
        const y = 90 - r - rise, cx = 270 + Math.round(Math.sin(r * 0.06) * 6), half = 9 + Math.round(r * 0.08);
        if (y < 44) break;
        fill(cx - half, y, half * 2 + 1, 1, r % 5 === 0 ? skinDark : skin); dot(cx - half, y, skinLight); dot(cx + half, y, skinDark);
      }
      // The maw, facing us, ringed with teeth
      const mx = 275, my = 52 - rise, rr = 11 + Math.round(wide * 2);
      disc(mx, my, rr, skin); disc(mx, my, rr - 2, 0x3a1a10); disc(mx, my, rr - 5, throat); disc(mx, my, rr - 8, 0xffb060);
      for (let k = 0; k < 18; k++) { const a = (k / 18) * Math.PI * 2; dot(mx + Math.round(Math.cos(a) * (rr - 3)), my + Math.round(Math.sin(a) * (rr - 3)), tooth); }
      ring(mx, my, rr, skinLight, 0.8);
      // Sand pouring, and the dune at its base
      for (let k = 0; k < 6; k++) { const ph = (now * 0.8 + k / 6) % 1; dot(262 + k * 5, 70 + Math.round(ph * 20), sand, 1 - ph); }
      for (let x = 246; x < 308; x++) { const h = 6 + Math.round(Math.sin((x - 246) * 0.05) * 4); fill(x, 95 - h, 1, h, sand); dot(x, 95 - h, 0xe8c08a); if ((x + h) % 5 === 0) dot(x, 97 - h, sandDark); }
      glowAt(mx, my, rr, rr, 0xff8a40, isNight ? 0.12 : 0.06);
      if (isNight) glowLate(() => { glowAt(mx, my, rr + 2, rr + 2, 0xff7a30, 0.22); disc(mx, my, rr - 8, 0xffc070, 0.6); });
    }

