      for (let gx = 264; gx < 298; gx += 3) dot(gx, 87, sand, 0.4);
      for (const [sx, sy, c] of [[268, 86, star], [292, 85, 0xf06a9a]]) { for (const a of [0, 1.26, 2.51, 3.77, 5.03]) dot(sx + Math.round(Math.cos(a - 1.57) * 2), sy + Math.round(Math.sin(a - 1.57) * 2), c); dot(sx, sy, shaded(c, 0.8)); }
