      fill(262, 56, 30, 26, rock); fill(262, 56, 30, 1, 0x8a7e70);
      for (let i = 0; i < 18; i++) { const h = hash(i, 7), gx = 266 + (h % 22), gy = 62 + ((h >> 3) % 16), hh = 3 + (h % 4), c = [amy, amyL, amyD][h % 3]; fill(gx, gy - hh, 2, hh, c); dot(gx, gy - hh, amyL); dot(gx, gy, amyD); }
      for (const [gx, gy] of [[272, 66], [282, 70], [276, 74]]) dot(gx, gy, WHITE, 0.6);
