      fill(254, 94, 48, 1, SHADOW);
      fill(276, 88, 4, 6, trunk);
      for (const [px, py, c] of [[262, 88, 0xc62828], [268, 90, 0xe8c24a], [286, 89, 0x4c8bf5], [292, 90, 0x2e8b3e]]) { fill(px, py, 6, 5, c); fill(px, py, 6, 1, shaded(c, 1.2)); fill(px + 2, py, 1, 5, shaded(c, 0.7)); }
