      fill(260, 80, 36, 12, desk); fill(260, 80, 36, 1, deskL); fill(260, 91, 36, 1, 0x2a2620);
      fill(280, 68, 16, 12, radio); fill(280, 68, 16, 1, radioL); fill(280, 79, 16, 1, 0x242a24);
      disc(284, 73, 3, screen); const a = now * (someone ? 3 : 1.5); line(284, 73, 284 + Math.round(Math.cos(a) * 3), 73 + Math.round(Math.sin(a) * 3), greenL); ring(284, 73, 3, 0x2a3a2e); dot(284 + Math.round(Math.cos(a - 0.5) * 2), 73 + Math.round(Math.sin(a - 0.5) * 2), green);
      fill(289, 70, 5, 3, screen); fill(289, 71, 1 + (Math.floor(now * 4) % 5), 1, green);
      for (const dx of [281, 284, 287, 290]) dot(dx, 77, dial);
      fill(264, 72, 1, 8, steel); fill(262, 72, 5, 1, steel); fill(262, 73, 1, 3, steelD); fill(266, 73, 1, 3, steelD);
      fill(270, 76, 1, 4, 0x2a2e28); fill(269, 74, 3, 2, 0x3a3e46);
      fill(276, 70, 1, 10, steel); fill(272, 66, 5, 1, steel); fill(271, 65, 3, 2, 0x3a3e46); if (someone) dot(272, 67, 0xffd36b);
