      const someone = atCorner(0);
      fill(252, 93, 52, 1, SHADOW);
      fill(256, 50, 44, 42, back); fill(256, 50, 1, 42, steel); fill(299, 50, 1, 42, steelD);
      for (let sh = 0; sh < 4; sh++) { const sy = 56 + sh * 9; fill(256, sy, 44, 1, steel); fill(256, sy, 44, 1, 0x6e727c); }
      for (let i = 0; i < 9; i++) { const cx = 258 + ((i * 4.6) | 0); fill(cx, 51, 3, 4, can); fill(cx, 51, 3, 1, canL); fill(cx, 52, 3, 1, label); }
      for (let i = 0; i < 4; i++) { const cx = 258 + i * 7; fill(cx, 60, 5, 4, water); fill(cx, 60, 5, 1, 0x6aa8c0); }
      fill(288, 59, 8, 5, label); fill(290, 60, 2, 3, cross); fill(289, 61, 4, 1, cross);
      fill(258, 69, 12, 4, crate); fill(258, 69, 12, 1, 0xa8824a); fill(272, 69, 10, 4, crate); fill(272, 69, 10, 1, 0xa8824a);
      fill(285, 67, 7, 6, 0x5a5a3a); fill(285, 67, 7, 1, 0x6a6a46); line(286, 68, 290, 72, 0x3a3a24); line(290, 68, 286, 72, 0x3a3a24);
      for (let i = 0; i < 3; i++) { const cx = 259 + i * 14; fill(cx, 77, 11, 5, barrel); fill(cx, 77, 11, 1, 0x4ac070); fill(cx, 81, 11, 1, barrelD); fill(cx + 4, 76, 3, 1, barrelD); }
      for (let i = 0; i < 5; i++) { const cx = 258 + i * 8; fill(cx, 86, 8, 4, sand); fill(cx, 86, 8, 1, 0xb8a878); fill(cx, 89, 8, 1, sandD); dot(cx + 4, 87, sandD); }
      fill(257, 52, 2, 2, 0x2a2e28); dot(258, 53, someone ? 0xfff0c0 : glow);
      if (isNight) glowLate(() => glowAt(258, 53, 3, 3, glow, 0.14));
