    /** A great round bank-vault blast door set into the lounge wall, riveted and hinged, its spoked wheel turning a notch every 20 s — and spinning while someone inspects it — with a keypad that glows red, green while it's worked; a dark sliver shows it never quite seals. */
    function drawParadisevault() {
      const someone = atCorner(0);
      const steel = 0x6e727c, steelLight = 0xa8adb6, steelDark = 0x4a4e58, frame = 0x3a3d47, brass = 0xc8a050, red = 0xff3a2a, green = 0x5ae88a;
      const cx = 276, cy = 70;
      fill(256, 95, 44, 2, SHADOW);
      fill(258, 48, 38, 48, frame); fill(258, 48, 38, 1, 0x555a66); fill(258, 48, 1, 48, 0x555a66); fill(295, 48, 1, 48, 0x24262c);
      for (let k = 0; k < 7; k++) { dot(261, 51 + k * 6, steel); dot(293, 51 + k * 6, steelDark); }
      disc(cx, cy, 18, steel); ring(cx, cy, 18, steelDark); disc(cx, cy, 16, steelLight, 0.14);
      for (let k = 0; k < 16; k++) { const a = (k / 16) * Math.PI * 2; dot(cx + Math.round(Math.cos(a) * 16), cy + Math.round(Math.sin(a) * 16), steelDark); }
      fill(256, cy - 6, 4, 12, steelDark); dot(257, cy - 4, brass); dot(257, cy + 4, brass);
      fill(cx + 17, cy - 10, 1, 20, 0x0d0f14);
      const spin = someone ? now * 1.4 : Math.floor(now / 20) * 0.6;
      ring(cx, cy, 9, steelDark); disc(cx, cy, 2.4, steelLight);
      for (let k = 0; k < 4; k++) { const a = spin + k * Math.PI / 2; line(cx, cy, cx + Math.round(Math.cos(a) * 9), cy + Math.round(Math.sin(a) * 9), steel); dot(cx + Math.round(Math.cos(a) * 9), cy + Math.round(Math.sin(a) * 9), steelLight); }
      fill(288, cy + 10, 6, 8, 0x1a1d22); for (let r = 0; r < 3; r++) for (let c = 0; c < 2; c++) dot(290 + c * 2, cy + 12 + r * 2, steelDark);
      const lit = someone ? green : red;
      dot(291, cy + 11, lit, 0.7 + 0.3 * Math.sin(now * 4));
      if (isNight) glowLate(() => glowAt(291, cy + 11, 3, 3, lit, 0.25));
    }

    /** A wall of eight little surveillance screens watching the too-perfect town outside — one drops to red snow now and then, faster while someone watches — over a steel shelf of emergency supplies: water jugs, ration cans and a first-aid box. */
    function drawParadisesurveil() {
      const someone = atCorner(0);
      const frame = 0x2a2d35, frameLight = 0x454a56, screen = 0x16352a, grass = 0x3a7a46, house = 0xd8cdb8, roof = 0x8a4a36, sky = 0x4a6a7a, steel = 0x6e727c, steelDark = 0x4a4e58, red = 0xd81a1a, water = 0x6fb8e8, can = 0xb8884a;
      fill(252, 95, 52, 2, SHADOW);
      fill(254, 46, 48, 30, frame); fill(254, 46, 48, 1, frameLight); fill(254, 75, 48, 1, 0x14161b);
      const rate = someone ? 4 : 9;
      for (let i = 0; i < 8; i++) {
        const sx = 256 + (i % 4) * 11, sy = 48 + Math.floor(i / 4) * 13;
        const glitch = ((now + i * 1.3) % rate) < 0.5 && i === (Math.floor(now / rate) % 8);
        fill(sx, sy, 10, 11, glitch ? 0x5a1a1a : screen);
        if (glitch) { for (let k = 0; k < 5; k++) fill(sx, sy + 1 + k * 2, 10, 1, 0x8a2a2a, 0.6); dot(sx + 5, sy + 5, 0xff6a5a); }
        else {
          fill(sx, sy, 10, 5, sky); fill(sx, sy + 6, 10, 5, grass);
          fill(sx + 3, sy + 4, 4, 3, house); fill(sx + 3, sy + 3, 4, 1, roof);
          if (i % 3 === 0) dot(sx + 7, sy + 8, 0xe8d0a0);
        }
        fill(sx, sy, 10, 1, 0xffffff, 0.08);
      }
      fill(256, 86, 44, 2, steelDark); fill(256, 85, 44, 1, steel);
      for (const [bx, col] of [[258, water], [262, water], [288, can], [292, can]]) { fill(bx, 80, 3, 5, col); fill(bx, 80, 3, 1, shaded(col, 1.15)); dot(bx, 81, WHITE, 0.3); }
      fill(270, 79, 8, 6, 0xeae6dc); fill(270, 79, 8, 1, 0xffffff); fill(273, 80, 2, 4, red); fill(272, 81, 4, 2, red);
      if (isNight) glowLate(() => glowAt(278, 60, 24, 16, 0x3a7a66, 0.12));
    }

    /** A transporter pad: a raised circular pad with a ring of amber emitter stations in an alcove; a column of sparkle beams down every few seconds, and the whole while someone is working the console. */
    function drawStartrektransporter() {
      const someone = atCorner(0);
      const alcove = 0x2a3142, alcoveLight = 0x3a4458, pad = 0x3a4048, padLight = 0x5a6478, ring = 0xd4a02a, beam = 0x9ad0f0, white = 0xffffff;
      const cx = 278, floor = 95;
      fill(256, 95, 44, 2, SHADOW);
      fill(258, 44, 40, 50, alcove); fill(258, 44, 40, 1, alcoveLight); fill(258, 44, 1, 50, alcoveLight);
      for (let k = 0; k < 7; k++) { const px = 262 + k * 5; fill(px, 47, 3, 2, ring, 0.8); dot(px + 1, 47, 0xf2d87a); }
      for (let dy = 0; dy < 4; dy++) fill(cx - 14 + dy, floor - 4 + dy, 28 - dy * 2, 1, dy === 0 ? padLight : pad);
      ellipseRing(cx, floor - 2, 13, 3, ring, 0.7);
      for (let k = 0; k < 7; k++) { const a = (k / 7) * Math.PI * 2, px = cx + Math.round(Math.cos(a) * 11), py = floor - 2 + Math.round(Math.sin(a) * 2.4); fill(px - 1, py - 1, 2, 2, alcoveLight); dot(px, py - 1, beam, 0.6); }
      const t = now % 6;
      if (someone || t < 2.5) {
        const phase = someone ? (now % 2) / 2 : t / 2.5;
        for (let k = 0; k < 5; k++) { const bx = cx - 10 + k * 5, h = Math.round((1 - Math.abs(phase - 0.5) * 2) * 44); for (let yy = 0; yy < h; yy += 2) dot(bx + ((hash(k * 7, yy) >> 3) % 3) - 1, 50 + yy, (hash(k, yy) % 2) ? beam : white, 0.5 * (1 - yy / 48)); }
      }
      if (isNight) glowLate(() => { for (let k = 0; k < 7; k++) { const px = 262 + k * 5; glowAt(px + 1, 48, 3, 3, ring, 0.12); } glowAt(cx, floor - 2, 14, 4, beam, 0.1); });
    }

    /** A warp core: a vertical glowing column in a steel housing, its light pulsing up and down with plasma rings travelling through it — faster while someone tends it; it glows blue, more at night. */
    function drawStartrekwarpcore() {
      const someone = atCorner(0);
      const frame = 0x3a4458, frameLight = 0x5a6478, dark = 0x1a1f28, core = 0x6ab0e8, coreBright = 0xc8e8ff, plasma = 0x9a6ad0;
      const cx = 278;
      fill(266, 95, 24, 2, SHADOW);
      fill(cx - 7, 44, 14, 52, frame); fill(cx - 7, 44, 14, 1, frameLight);
      fill(cx - 8, 44, 2, 52, frame); fill(cx + 6, 44, 2, 52, frame);
      fill(cx - 9, 43, 18, 3, frame); fill(cx - 9, 92, 18, 4, frame); fill(cx - 9, 43, 18, 1, frameLight);
      fill(cx - 4, 47, 8, 45, dark);
      const speed = someone ? 3 : 1.2;
      for (let y = 47; y < 92; y += 1) {
        const s = Math.sin((y - now * 18 * speed) * 0.5), w = s > 0.3 ? 8 : 5, bright = (s + 1) / 2;
        fill(cx - Math.floor(w / 2), y, w, 1, bright > 0.6 ? coreBright : core, 0.5 + bright * 0.5);
      }
      for (let k = 0; k < 3; k++) { const py = 90 - Math.floor((now * 20 * speed + k * 15) % 45); fill(cx - 5, py, 10, 1, plasma, 0.6); fill(cx - 6, py, 12, 1, plasma, 0.3); }
      dot(cx, 45, coreBright); dot(cx, 94, coreBright);
      glowAt(cx, 68, 10, 24, core, isNight ? 0.18 : 0.1);
      if (isNight) glowLate(() => glowAt(cx, 68, 12, 28, core, 0.2));
    }

    /** A chesterfield lounge: a buttoned oxblood-leather sofa with a cushion, beside a wooden globe drinks-bar on a tripod stand that cracks open to show bottles when someone's near. */
