      const balls = [[270, 77, 0xf0e8d8], [276, 76, 0xc83a2a], [282, 78, 0xf2d35b], [288, 77, 0x2a2d35]];
      for (const [bx, by, c] of balls) { disc(bx, by, 1.6, c); dot(bx - 1, by - 1, WHITE, 0.5); }
