    /**
     * A launch pad model: a white rocket by its lattice tower on a black plinth with a lit pad. Every 45 s, or every 12 s
     * with someone at its console, the lights count down, smoke billows and the rocket lifts on its flame for a few
     * seconds before settling back on the pad.
     */
    function drawGroklaunch() {
      const plinth = 0x1a1b20, plinthLight = 0x3a3d47, plinthDark = 0x0e0f12, steel = 0x8a8e98, steelDark = 0x5a5e68;
      const body = 0xf4f1ea, bodyDark = 0xc8ccd4, band = 0x1a1b20, flame = 0xffb648;
      const period = atCorner(0) ? 12 : 45, t = (now + 7) % period;
      const lift = t >= 2 && t < 7 ? Math.round(Math.sin(((t - 2) / 5) * Math.PI) * 12) : 0, burning = t >= 1.6 && t < 6.4;
      fill(260, 93, 36, 1, SHADOW);
      // The plinth, its console at the front and its pad
      fill(261, 84, 34, 9, plinth); fill(261, 84, 34, 1, plinthLight); fill(261, 84, 1, 9, plinthLight); fill(294, 84, 1, 9, plinthDark);
      fill(270, 82, 16, 2, 0x2a2c33); fill(270, 82, 16, 1, 0x5a5e68);
      grokMark(266, 89, 0x6e727c);
      // The countdown: three lights going white, then the pad's ring lit
      const count = t < 1.6 ? Math.floor(t / 0.55) + 1 : burning ? 3 : 0;
      const lamps = () => { for (let k = 0; k < 3; k++) dot(282 + k * 3, 89, k < count ? WHITE : 0x3a3d47); };
      lamps();
      // The tower: a lattice of steel with an arm reaching the rocket
      fill(265, 52, 1, 30, steel); fill(268, 52, 1, 30, steelDark);
      for (let yy = 54; yy < 82; yy += 4) { line(265, yy, 268, yy + 3, steelDark); dot(266, yy, steel); }
      fill(264, 51, 6, 1, steel); dot(266, 50, 0xff6a5a);
      fill(269, lift ? 62 : 64, 6, 1, steelDark);
      // The smoke, rolling off the pad as it goes
      if (burning) for (let k = 0; k < 6; k++) {
        const g = (t - 1.6) * 3 + k * 0.7, side = k % 2 ? 1 : -1, sx = 278 + side * Math.round(2 + (g % 4) * 2), sy = 81 - Math.floor(g % 3);
        disc(sx, sy, 1.6 + (k % 3) * 0.5, 0xe8e6e0, 0.75 - (g % 4) * 0.15);
      }
      // The rocket
      const top = 56 - lift;
      fill(276, top + 4, 5, 22, body); fill(276, top + 4, 1, 22, WHITE); fill(280, top + 4, 1, 22, bodyDark);
      fill(277, top + 2, 3, 2, body); dot(278, top + 1, bodyDark); dot(278, top, 0xa8adb6);
      fill(276, top + 10, 5, 2, band); fill(276, top + 19, 5, 1, band, 0.7); dot(278, top + 7, 0x8ab4ff);
      fill(275, top + 21, 1, 5, 0x2a2c33); fill(281, top + 21, 1, 5, 0x2a2c33); fill(274, top + 24, 1, 2, 0x2a2c33); fill(282, top + 24, 1, 2, 0x2a2c33);
      const fire = () => {
        if (!burning) return;
        const flick = Math.floor(now * 14) % 2;
        fill(277, top + 26, 3, 2 + flick, flame); dot(278, top + 28 + flick, 0xfff0c0); dot(278, top + 26, WHITE);
        glowAt(278, top + 28, 4, 3, flame, 0.25);
      };
      fire();
      if (isNight) glowLate(() => { lamps(); fire(); dot(266, 50, 0xff6a5a); });
    }

    /** A pair of server racks: two black cabinets under a cable tray, their lights blinking; faster with someone working at them. */
    function drawGrokbotrack() {
      const busy = atCorner(0), tray = 0x6e727c, trayDark = 0x3a3d47;
      fill(262, 52, 38, 2, tray); for (let x = 263; x < 300; x += 3) dot(x, 54, trayDark);
      fill(263, 46, 1, 6, trayDark); fill(298, 46, 1, 6, trayDark);
      for (const rx of [268, 281]) [0x8ab4ff, 0xf4f1ea, 0x6e727c].forEach((c, k) => fill(rx + 3 + k * 2, 54, 1, 3, c));
      drawGrokRack(267, 93, 36, busy);
      drawGrokRack(280, 93, 36, busy);
    }

    /* The pet */
    /** The cat café's cats, one look each: fur, markings, eyes and nose, and build (0 kitten, 1 cat, 2 big). */
