      catcafepersian: { fur: 0xf2e2c0, dark: 0xd8c4a0, light: 0xfff6e4, eye: 0xd8782a, nose: 0xe8a0a0, mark: 'solid', fluffy: true, flat: true, build: 1 },
      catcafetortie: { fur: 0x2e2422, dark: 0xc8702a, patch: 0x8a4a2a, light: 0x4a3a34, eye: 0xe8b030, nose: 0x5a3a34, mark: 'tortie', build: 1 },
      catcafesphynx: { fur: 0xe8c0b0, dark: 0xc89888, light: 0xf2d4c8, eye: 0x5ab8d8, nose: 0xe89090, mark: 'solid', bald: true, jumper: 0x4a8ad8, build: 1 },
      catcafekitten: { fur: 0x8a8a90, dark: 0x5a5a62, light: 0xf6f2ea, eye: 0x5aa8e8, nose: 0xf2a0b0, mark: 'bib', build: 0 },
      catcafemaine: { fur: 0x7a5a3a, dark: 0x4a3420, light: 0xe8dcc4, eye: 0xd8b030, nose: 0x6a4a3a, mark: 'tabby', fluffy: true, tufts: true, build: 2 },
