        front(x, y, o) { fill(x - 2, y, 5, 1, shaded(o.shirt, 1.25)); for (const r of [2, 4]) { fill(x - 1, y + r, 3, 1, PALETTE.brass); dot(x, y + r, 0xf2d38a); } },
